'use strict';
// Аналитика: выручка по контрагентам
/* ═════════════ Аналитика: выручка по контрагентам ═════════════ */
const REV=[['fee','Обслуживание','var(--blue)'],['proj','Проекты','var(--purple)'],['svc','Разовые услуги','var(--orange)']];
function revenueData(y){const ys=String(y);const rows=visCps(true).map(c=>({c,fee:0,proj:0,svc:0,m:Array.from({length:12},()=>[0,0,0])}));const by={};rows.forEach(r=>by[r.c.id]=r);
  const add=(cp,date,k,a)=>{if(!date||!date.startsWith(ys))return;const r=by[cp];if(!r)return;r.m[+date.slice(5,7)-1][k]+=a;r[REV[k][0]]+=a};
  FEEPAYS.forEach(f=>{if(!f.del)add(f.cp,f.date,0,f.amount)});PROJECTS.forEach(p=>p.pays.forEach(x=>{if(!x.del)add(p.cp,x.date,1,x.amount)}));SERVICES.forEach(s=>{if(!s.del)s.pays.forEach(x=>{if(!x.del)add(s.cp,x.date,2,x.amount)})});
  const lastM=ys===TODAY.slice(0,4)?ym(TODAY):ys+'-12';
  rows.forEach(r=>{const c=r.c;r.feeCh=0;if(c.kind!=='oneoff')for(let mo=1;mo<=12;mo++){const m=`${ys}-${String(mo).padStart(2,'0')}`;if(m>lastM||m<c.start.slice(0,7)||!inService(c,m))continue;r.feeCh+=feeCharge(c,m)}
    r.svcCh=SERVICES.filter(s=>!s.del&&s.cp===c.id&&s.date.startsWith(ys)).reduce((a,s)=>a+s.amount,0);
    r.svcDebt=SERVICES.filter(s=>!s.del&&s.cp===c.id).reduce((a,s)=>a+Math.max(0,s.amount-svcPaid(s)),0);
    r.debt=(c.feeDebt||0)+r.svcDebt;r.total=r.fee+r.proj+r.svc});return rows}
function niceStep(max){const raw=max/4;const p=Math.pow(10,Math.floor(Math.log10(raw||1)));const n=raw/p;return (n<=1?1:n<=2?2:n<=2.5?2.5:n<=5?5:10)*p}
const kSom=v=>v>=1e6?(v/1e6).toFixed(1).replace('.',',').replace(',0','')+' млн':v>=1000?Math.round(v/1000)+' тыс.':String(v);
function monthChart(tm,prev,cmp,last){const W=760,H=250,L=56,B=28,T=10;const cw=(W-L-8)/12;const max=Math.max(1,...tm.map(x=>x[0]+x[1]+x[2]),...(cmp?prev:[0]));const st=niceStep(max);const top=Math.ceil(max/st)*st;const yv=v=>H-B-(v/top)*(H-B-T);
  let g='';for(let v=0;v<=top+.1;v+=st)g+=`<line x1="${L}" x2="${W-8}" y1="${yv(v)}" y2="${yv(v)}" stroke="var(--border)" stroke-width="1"/><text x="${L-8}" y="${yv(v)+4}" text-anchor="end" font-size="11" fill="var(--muted)">${kSom(v)}</text>`;
  let b='';tm.forEach((m,i)=>{const x0=L+i*cw;const bw=Math.min(30,cw*.46);const bx=x0+(cw-bw)/2+(cmp?bw*.28:0);
    if(cmp&&prev[i]>0){const px=bx-bw*.62;const ph=yv(0)-yv(prev[i]);b+=`<rect x="${px}" y="${yv(prev[i])}" width="${bw*.5}" height="${ph}" rx="3" fill="var(--border-strong)" opacity=".55"><title>${MONTHS[i]} ${'прошлого года'}: ${som(prev[i])}</title></rect>`}
    let acc=0;const tot=m[0]+m[1]+m[2];m.forEach((v,k)=>{if(v<=0)return;const y1=yv(acc+v),y0=yv(acc);const h=Math.max(1,y0-y1-(acc>0?2:0));const isTop=acc+v===tot;b+=`<rect x="${bx}" y="${y1}" width="${bw}" height="${h}" rx="${isTop?4:0}" fill="${REV[k][2]}"><title>${MONTHS[i]}: ${REV[k][1].toLowerCase()} ${som(v)}</title></rect>`;acc+=v});
    if(tot>0)b+=`<rect x="${x0}" y="${T}" width="${cw}" height="${H-B-T}" fill="transparent"><title>${MONTHS[i][0].toUpperCase()+MONTHS[i].slice(1)}: всего ${som(tot)}${cmp?`, год назад ${som(prev[i])}`:''}\n${REV.map((r,k)=>`${r[1]}: ${som(m[k])}`).join('\n')}</title></rect>`;
    b+=`<text x="${x0+cw/2}" y="${H-8}" text-anchor="middle" font-size="11" fill="${i>last?'var(--faint)':'var(--muted)'}">${MONTHS[i].slice(0,3)}</text>`});
  return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Выручка по месяцам" style="display:block;max-height:280px">${g}<line x1="${L}" x2="${W-8}" y1="${yv(0)}" y2="${yv(0)}" stroke="var(--border-strong)"/>${b}</svg>`}
function shareChart(rows){const top=rows.filter(r=>r.total>0).sort((a,b)=>b.total-a.total).slice(0,10);if(!top.length)return '<span class="faint">Нет поступлений за год</span>';const max=top[0].total;
  return `<div style="display:flex;flex-direction:column;gap:7px">${top.map(r=>`<div class="clk" data-an="${r.c.id}" title="${esc(r.c.name)}: ${som(r.total)}" style="display:grid;grid-template-columns:minmax(90px,170px) 1fr auto;gap:8px;align-items:center;font-size:12.5px;cursor:pointer"><span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(r.c.name)}</span><span style="display:flex;gap:2px;height:12px">${REV.map((x,k)=>r[x[0]]>0?`<i style="display:block;height:12px;width:${r[x[0]]/max*100}%;background:${x[2]};border-radius:${k===REV.length-1||!REV.slice(k+1).some(y=>r[y[0]]>0)?'0 4px 4px 0':'0'}" title="${x[1]}: ${som(r[x[0]])}"></i>`:'').join('')}</span><span class="tnum muted">${kSom(r.total)}</span></div>`).join('')}</div>`}
function renderAnalytics(body){
  if(!CPS.length&&!FEEPAYS.length&&!SERVICES.length){body.innerHTML=`<div class="box"><h3>Выручка по месяцам</h3><svg viewBox="0 0 600 180" width="100%" height="180" role="img" aria-label="Пустой график" style="display:block">${[0,1,2,3].map(i=>`<line x1="40" x2="590" y1="${20+i*45}" y2="${20+i*45}" stroke="var(--border)"/>`).join('')}${MONTHS.map((m,i)=>`<text x="${62+i*45}" y="176" text-anchor="middle" font-size="11" fill="var(--faint)">${m.slice(0,3)}</text>`).join('')}</svg><div class="state" style="padding:6px 0 4px"><span>Данные появятся после первых начислений</span></div></div>`;return}
  const a=S.an=S.an||{y:+TODAY.slice(0,4),cmp:true};const cy=+TODAY.slice(0,4);const rows=revenueData(a.y),prev=revenueData(a.y-1);const pm={};prev.forEach(r=>pm[r.c.id]=r);
  const last=a.y===cy?+TODAY.slice(5,7)-1:11;const tm=Array.from({length:12},(_,i)=>[0,1,2].map(k=>rows.reduce((s,r)=>s+r.m[i][k],0)));const ptm=Array.from({length:12},(_,i)=>prev.reduce((s,r)=>s+r.m[i][0]+r.m[i][1]+r.m[i][2],0));
  const sum=k=>rows.reduce((s,r)=>s+r[k],0);const tot=sum('total');const ytdPrev=ptm.slice(0,last+1).reduce((s,v)=>s+v,0);const ch=ytdPrev?Math.round((tot-ytdPrev)/ytdPrev*100):null;
  body.innerHTML=`<div class="row"><span class="muted">Выручка организации — оплаты от контрагентов за обслуживание, проекты и разовые услуги (в том числе от разовых контрагентов). Налоги контрагентов сюда не входят.</span><div class="grow"></div>${sel('an-y',[cy,cy-1].map(y=>[y,y+' год']),a.y,'style="width:auto;min-height:30px;padding:3px 8px"')}<label class="row" style="gap:6px"><input type="checkbox" id="an-cmp" ${a.cmp?'checked':''}> Сравнить с ${a.y-1}</label></div>
  <div class="plates">${plate({id:'ch',icon:'list',color:'blue',label:`Начислено за обслуживание`,value:fmtM(sum('feeCh'),false),unit:'сом',sub:`оплачено ${sum('feeCh')?Math.round(sum('fee')/sum('feeCh')*100):0} %`})}${plate({id:'t',icon:'chart',color:'green',label:`Выручка за ${a.y}${a.y===cy?' (с начала года)':''}`,value:fmtM(tot,false),unit:'сом',sub:ch==null?'':`${ch>=0?'+':''}${ch} % к тому же периоду ${a.y-1}`})}
    ${REV.map(([k,l],i)=>plate({id:k,icon:['coins','briefcase','gift'][i],color:['blue','purple','orange'][i],label:l,value:fmtM(sum(k),false),unit:'сом',sub:tot?Math.round(sum(k)/tot*100)+' % выручки':''})).join('')}
    ${plate({id:'debt',icon:'alert',color:sum('debt')?'red':'green',label:'Долг сейчас',value:fmtM(sum('debt'),false),unit:'сом',sub:'обслуживание и разовые услуги'})}</div>
  <div class="box"><h3>Выручка по месяцам<span class="grow"></span><span class="row" style="gap:12px;text-transform:none;letter-spacing:0;font-weight:500;font-size:12.5px">${REV.map(r=>`<span class="row" style="gap:5px"><i style="width:10px;height:10px;border-radius:3px;background:${r[2]};display:inline-block"></i>${r[1]}</span>`).join('')}${a.cmp?`<span class="row" style="gap:5px"><i style="width:10px;height:10px;border-radius:3px;background:var(--border-strong);opacity:.55;display:inline-block"></i>${a.y-1} год</span>`:''}</span></h3>${monthChart(tm,ptm,a.cmp,last)}</div>
  <div class="cols2"><div class="box"><h3>Топ-10 контрагентов по выручке</h3>${shareChart(rows)}<span class="hint">Нажмите на контрагента, чтобы открыть его операции.</span></div>
  <div class="box"><h3>Концентрация</h3>${(()=>{const s=rows.filter(r=>r.total>0).sort((x,y)=>y.total-x.total);const t5=s.slice(0,5).reduce((q,r)=>q+r.total,0);const n=s.length;const deb=visCps().filter(c=>c.feeDebt>0);return `<div class="kv"><div><span class="k">Платили в ${a.y}</span><span class="v">${n} ${plural(n,'контрагент','контрагента','контрагентов')}</span></div><div><span class="k">Доля топ-5</span><span class="v tnum">${tot?Math.round(t5/tot*100):0} %</span></div><div><span class="k">Средний чек за год</span><span class="v tnum">${som(n?Math.round(tot/n):0)}</span></div><div><span class="k">Долг за обслуживание сейчас</span><span class="v tnum ${deb.length?'red strong':''}">${som(deb.reduce((q,c)=>q+c.feeDebt,0))}</span></div></div>`})()}</div></div>
  <div id="ang"></div>`;
  $('#an-y',body).onchange=e=>{a.y=+e.target.value;renderPage()};$('#an-cmp',body).onchange=e=>{a.cmp=e.target.checked;renderPage()};
  $$('[data-an]',body).forEach(x=>x.onclick=()=>cpOps(CPM[+x.dataset.an]));
  grid($('#ang',body),{id:'an-cps',audit:false,rid:r=>r.c.id,cols:[
    {key:'cp',label:'Контрагент',type:'text',w:240,val:r=>r.c.name,html:r=>`<span class="strong">${esc(r.c.name)}</span>`},{key:'resp',label:'Ответственный',type:'enum',w:130,val:r=>empName(r.c.resp)},{key:'kind',label:'Тип',type:'enum',w:120,val:r=>r.c.kind==='oneoff'?'Разовое':'Постоянное',hide:true},
    {key:'feeCh',label:'Начислено за обслуживание',type:'money',w:190,num:true,total:true,val:r=>r.feeCh},{key:'fee',label:'Оплачено за обслуживание',type:'money',w:190,num:true,total:true,val:r=>r.fee},{key:'proj',label:'Проекты',type:'money',w:130,num:true,total:true,val:r=>r.proj},{key:'svc',label:'Разовые услуги',type:'money',w:140,num:true,total:true,val:r=>r.svc},
    {key:'total',label:'Итого получено',type:'money',w:150,num:true,total:true,val:r=>r.total,html:r=>`<b>${fmtM(r.total)}</b>`},{key:'debt',label:'Долг',type:'money',w:130,num:true,total:true,val:r=>r.debt,html:r=>r.debt>0?`<span class="red strong">${fmtM(r.debt)}</span>`:'<span class="faint">0,00</span>'},{key:'share',label:'Доля',type:'num',w:90,num:true,val:r=>tot?Math.round(r.total/tot*1000)/10:0,html:r=>(tot?String(Math.round(r.total/tot*1000)/10).replace('.',','):'0')+' %'},
    {key:'prev',label:`${a.y-1} год`,type:'money',w:130,num:true,total:true,val:r=>pm[r.c.id]?pm[r.c.id].total:0,hide:!a.cmp},
    {key:'ch',label:'Изменение',type:'num',w:120,num:true,val:r=>{const p=pm[r.c.id]?pm[r.c.id].total:0;return p?Math.round((r.total-p)/p*100):null},html:r=>{const p=pm[r.c.id]?pm[r.c.id].total:0;if(!p)return '<span class="faint">—</span>';const v=Math.round((r.total-p)/p*100);return `<span class="${v<0?'red':'green'}">${v>0?'+':''}${v} %</span>`},hide:!a.cmp}],
    rows:()=>rows.filter(r=>r.total>0||r.feeCh>0||r.debt>0||(pm[r.c.id]&&pm[r.c.id].total>0)),title:'cp',noun:['контрагент','контрагента','контрагентов'],sort:{key:'total',dir:-1},open:r=>cpOps(r.c),
    actions:r=>[{label:'Операции контрагента',icon:'list',run:()=>cpOps(r.c)},{label:'Карточка контрагента',icon:'building',run:()=>openCp(r.c)}]});
}

